def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Find horizontal bands of non-background cells.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # Choose the most-overlapping pair of bands with equal heights.
    pair = None
    for i in range(len(bands)):
        for j in range(i + 1, len(bands)):
            a0, a1 = bands[i]
            b0, b1 = bands[j]
            if a1 - a0 != b1 - b0:
                continue
            ma = [[grid[a0+y][x] != bg for x in range(w)]
                  for y in range(a1-a0)]
            mb = [[grid[b0+y][x] != bg for x in range(w)]
                  for y in range(b1-b0)]
            overlap = sum(ma[y][x] and mb[y][x]
                          for y in range(len(ma)) for x in range(w))
            if pair is None or overlap > pair[0]:
                pair = (overlap, a0, b0, ma, mb)

    if pair is None:
        return out

    _, a0, b0, ma, mb = pair
    height = len(ma)
    candidates = []

    # Find connected components of the non-matching cells in each direction.
    for side, (source, target) in enumerate(((ma, mb), (mb, ma))):
        remaining = {(y, x) for y in range(height) for x in range(w)
                     if source[y][x] and not target[y][x]}
        while remaining:
            start = min(remaining)
            remaining.remove(start)
            comp = {start}
            stack = [start]
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (ny, nx) in remaining:
                        remaining.remove((ny, nx))
                        comp.add((ny, nx))
                        stack.append((ny, nx))
            candidates.append((len(comp), side, comp))

    if candidates:
        largest = max(size for size, _, _ in candidates)
        # Include equally large repeated components of the same shape.
        winners = [(side, comp) for size, side, comp in candidates
                   if size == largest]
        for side, comp in winners:
            target_start = b0 if side == 0 else a0
            for y, x in comp:
                out[target_start + y][x] = 1

    return out
